/**
 * Loader for the cross-implementation test vectors in
 * `testdata/mpp/vectors.json`.
 *
 * The file is generated by the Go implementation of the Payment scheme, in
 * aperture's `mpp/mppvectors` package, and copied here verbatim. Nothing in
 * this repository edits it: it is a record of what the peer on the other end
 * of the wire actually does, and a hand-edited vector proves agreement with
 * nobody. Regenerate it with `go run ./cmd/gen-mpp-vectors -o -` from an
 * aperture checkout and copy the output over this one.
 *
 * Test-only. This module reads from the filesystem, so it is deliberately
 * absent from the package's entry points and must never be imported by
 * anything that ships: the runtime targets include Workers, where there is
 * no `node:fs`.
 */

import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

/** Challenge parameters as the vector file spells them, wire names and all. */
export interface VectorChallengeParams {
  id: string;
  realm: string;
  method: string;
  intent: string;
  request: string;
  expires?: string;
  digest?: string;
  description?: string;
  opaque?: string;
}

/** One RFC 8785 canonicalization case. */
export interface CanonicalVector {
  name: string;
  note?: string;

  /** The JSON text to canonicalize. */
  input: string;

  /** The expected canonical form, absent when `error` is set. */
  canonical?: string;

  /** Set when canonicalizing the input has to fail. */
  error?: boolean;
}

/** One base64url case. */
export interface Base64Vector {
  name: string;
  note?: string;

  encoded: string;

  /** Hex of the bytes `encoded` decodes to, absent when `error` is set. */
  decodedHex?: string;

  /**
   * Whether `encoded` is what encoding those bytes produces, as opposed to
   * merely a spelling the decoder accepts. Only a canonical vector can be
   * used to check the encoder.
   */
  canonical: boolean;

  /** Set when decoding `encoded` has to fail. */
  error?: boolean;
}

/** One emit-and-reparse case for a single challenge. */
export interface ChallengeHeaderVector {
  name: string;
  note?: string;

  /** What the emitter was handed. */
  params: VectorChallengeParams;

  /** The `WWW-Authenticate` field value it produced. */
  header: string;

  /** What parsing `header` yields. */
  parsed: VectorChallengeParams;
}

/** One parse case for a field value carrying more than one challenge. */
export interface ChallengeListVector {
  name: string;
  note?: string;

  header: string;

  /** The Payment challenges it carries, in order. */
  challenges?: VectorChallengeParams[];

  /** Set when the value carries no usable Payment challenge. */
  error?: boolean;
}

/** One HMAC binding case. Its `params.id` is the computed identifier. */
export interface ChallengeIdVector {
  name: string;
  note?: string;

  params: VectorChallengeParams;

  /** The pipe-delimited seven-slot string, so a mismatch can be localized. */
  hmacInput: string;
}

/** One `Authorization` header case. */
export interface CredentialVector {
  name: string;
  note?: string;

  /** The credential document before encoding, empty when `error` is set. */
  credentialJson: string;

  /** The complete field value. */
  header: string;

  /** Set when parsing `header` has to fail. */
  error?: boolean;
}

/** One `Payment-Receipt` header case. */
export interface ReceiptVector {
  name: string;
  note?: string;

  receiptJson: string;
  header: string;
}

export interface GoVectors {
  /** Schema version of the document, bumped when its shape changes. */
  version: number;

  description: string;

  /** The secret the `challengeIds` vectors were computed under, in hex. */
  hmacSecretHex: string;

  canonicalization: CanonicalVector[];
  base64url: Base64Vector[];
  challengeHeaders: ChallengeHeaderVector[];
  challengeLists: ChallengeListVector[];
  challengeIds: ChallengeIdVector[];
  credentials: CredentialVector[];
  receipts: ReceiptVector[];
}

/** The schema version this loader understands. */
const SUPPORTED_VERSION = 1;

/**
 * Read and parse the Go-generated vector file.
 *
 * The version is checked rather than assumed. A file whose shape has moved on
 * would otherwise arrive as a pile of undefined fields, and tests that loop
 * over nothing pass, which is the one way a vector suite can fail silently.
 */
export async function loadGoVectors(): Promise<GoVectors> {
  const here = dirname(fileURLToPath(import.meta.url));
  const path = join(here, "..", "..", "testdata", "mpp", "vectors.json");
  const parsed = JSON.parse(await readFile(path, "utf-8")) as GoVectors;

  if (parsed.version !== SUPPORTED_VERSION) {
    throw new Error(
      `mpp vectors: file is schema version ${parsed.version}, and this ` +
        `loader understands ${SUPPORTED_VERSION}`,
    );
  }

  return parsed;
}

/** Decode a lowercase hex string into bytes. */
export function fromHex(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

/** Render bytes as a lowercase hex string. */
export function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}
